


SELECT id, 'fa', 'گاماس بات', 'دستیار مطالعاتی تلگرام', 'دستیار مطالعاتی فارسی که صوت و اسناد آموزشی را به متن، جزوه، آزمون و فلش‌کارت تبدیل می‌کند.', 'گاماس بات یک دستیار مطالعاتی تلگرام است که فایل صوتی، ویدیو، پیام صوتی و اسناد آموزشی را به جریان‌های یادگیری ساخت‌یافته وصل می‌کند؛ از متن و جزوه تا آزمون، فلش‌کارت و خروجی فایل.', JSON_ARRAY('ورودی صوت، ویدیو، پیام صوتی و اسناد آموزشی مانند PDF و DOCX', 'متن‌نگاری، جزوه‌های ساخت‌یافته و ابزارهای مرور مانند آزمون و فلش‌کارت', 'کتابخانهٔ کاربر، پشتیبانی و جریان‌های خروجی برای فایل‌های متنی و اداری'), 'دانشجو کلاس را با گوشی ضبط می‌کند و بعد چیزی برای مطالعه ندارد: چند ساعت صوت، یا یک فایل PDF، و هیچ راه ساخت‌یافته‌ای برای مرور آن. تبدیل دستی این فایل‌ها به جزوه کند است و متن‌نگاریِ تنها چیزی تولید نمی‌کند که بشود از آن درس خواند.', 'یک ربات تلگرام که صوت، ویدیو، پیام صوتی، PDF، DOCX و پاورپوینت می‌گیرد و مواد مطالعاتی برمی‌گرداند: متن، جزوهٔ راست‌چین Word، آزمون، فلش‌کارت و خروجی فایل. هر فایل از یک بررسی ورود، یک صف کار محدود و کتابخانهٔ کاربر عبور می‌کند تا ربات زیر بار پاسخ‌گو بماند.', JSON_ARRAY('یک کلاینت Telethon با مراحل asyncio محدود و SQLite در حالت WAL؛ کارهای رسانه با PyAV در فرایندهای فرزندِ محدود اجرا می‌شوند، پس نه به صف پیام نیاز است، نه پایگاه‌دادهٔ خارجی و نه نصب سیستمی FFmpeg.', 'تولید جزوه از یک زنجیرهٔ مرتب از ارائه‌دهنده‌ها استفاده می‌کند: هر مسیر کلید، نشانی پایه و مدل خود را دارد، خطاهای گذرا با سقف مشخص تلاش دوباره می‌شوند و خطای قابل‌بازیابی به مسیر بعدی منتقل می‌شود.', 'خروجی مدل به‌صورت JSON سخت‌گیرانه تجزیه می‌شود، از نظر شکل جزوه و پایبندی به منبع اعتبارسنجی می‌گردد و بعد از آن رندر می‌شود. پاسخ بریده‌شده رد می‌شود، نه اینکه به‌صورت جزوهٔ ناقص تحویل داده شود.', 'برای یادداشت اسناد و تبدیل فایل‌های اداری، مسیرهای جایگزین قطعی وجود دارد؛ نبودِ کلید ارائه‌دهنده قابلیت را ساده‌تر می‌کند، آن را نمی‌شکند.', 'لاگ‌ها فقط فراداده و شمار توکن دارند؛ هرگز کلید، پرامپت یا متن رونویسی در آن‌ها نیست.'), 'یک فرایند پایتون که روی ویندوز یا هاست اشتراکی cPanel اجرا می‌شود و دور قابلیت‌های یادگیری، اعتبار و کیف پول، رسیدهای بررسی‌شده توسط مدیر، تیکت پشتیبانی و جریان معرفی دارد.', 'گاماس بات — دستیار مطالعاتی تلگرام | امیرعلی غمخوار', 'مروری بر گاماس بات، دستیار مطالعاتی تلگرام برای صوت، اسناد، جزوه و ابزارهای یادگیری.' FROM projects WHERE slug='gamas-bot';

SELECT id, 'fa', 'وب‌سایت گاماس', 'وب‌سایت محصول', 'صفحهٔ معرفی فارسی و راست‌چین گاماس، با خروجی ایستا و یک API سبک PHP برای هاست اشتراکی.', 'وب‌سایت گاماس یک صفحهٔ معرفی فارسی و راست‌چین برای ربات آموزشی است. معماری آن HTML ایستای ازپیش‌رندرشده را با یک API کوچک PHP برای ثبت آمار کلیک ترکیب می‌کند تا روی Apache و cPanel بدون فرایند دائمی Node اجرا شود.', JSON_ARRAY('رابط فارسی و راست‌چین با HTML ایستای ازپیش‌رندرشده', 'React 18، Vite 6 و vite-react-ssg در زنجیرهٔ ساخت', 'API سبک PHP 8.2+ و راهنمای استقرار روی Apache و cPanel'), 'ربات به یک خانهٔ عمومی نیاز داشت: یک صفحهٔ محصول فارسی و راست‌چین که روی هاست اشتراکیِ ایرانی سریع باشد؛ جایی که Node.js در دسترس نیست.', 'یک سایت ایستا با React 18 و Vite 6 که به HTML ازپیش‌رندرشده تبدیل می‌شود، همراه با یک API کوچک PHP 8.2 برای ثبت آمار کلیک، مستقرشده روی Apache در cPanel.', JSON_ARRAY('پیش‌رندرش ایستا با vite-react-ssg: هر مسیر به‌صورت HTML واقعی منتشر می‌شود، پس محتوا و فراداده برای خزنده‌ها قابل دیدن است، بدون هیچ فرایند سمت سرور.', 'قلم‌های وب فارسی میزبانیِ داخلی می‌شوند و تصویرها در زمان ساخت پردازش می‌گردند، تا صفحه به درخواستِ قلم یا CDN شخص ثالث وابسته نباشد.', 'API به مجموعه‌ای محدود از مسیرها با محدودسازی نرخِ درخواست و یک نقطهٔ دریافت گزارش CSP تقلیل یافته است.', 'قواعد Apache برای کش، فشرده‌سازی، سرایندهای امنیتی و بازگشت ایستای SPA، تا رفتار سایت روی هاست اشتراکی همان باشد که در پیش‌نمایش محلی است.'), 'صفحه‌ای که مجموعه‌ای از فایل‌های ایستا باقی می‌ماند: زمان‌اجرایی برای نگهداری ندارد، پایگاه‌داده‌ای برای پشتیبان‌گیری ندارد و آمار آن در یک استقرار کاملاً ایستا هم کار می‌کند.', 'وب‌سایت گاماس — تجربهٔ محصول ایستا | امیرعلی غمخوار', 'وب‌سایت فارسی گاماس؛ یک تجربهٔ محصول ایستا با React، Vite و API سبک PHP برای cPanel.' FROM projects WHERE slug='gamas-website';

SELECT id, 'fa', 'گفتار پزشکی فارسی', 'دیکتهٔ پزشکی بلادرنگ', 'ابزار دسکتاپ ویندوز برای دیکتهٔ پزشکی فارسی و انگلیسی؛ از نشست کوتاه‌عمر تا قالب‌بندی راست‌به‌چپ و تزریق متن.', 'این پروژه یک ابزار دیکتهٔ پزشکی بلادرنگ برای ویندوز است: صدا به نشست کوتاه‌عمر Deepgram می‌رود و متن از مسیر نرمال‌سازی، پردازش اصطلاحات و قالب‌بندی دوجهته عبور می‌کند تا در پنجره‌ای که در حال استفاده است تزریق شود.', JSON_ARRAY('پشتیبانی از دیکتهٔ گفتاری فارسی و انگلیسی روی ویندوز', 'توکن نشست کوتاه‌عمر از میزبان تحت کنترل صاحب سامانه؛ کلید Deepgram در برنامهٔ دسکتاپ نیست', 'پردازش قطعی اصطلاحات و متن، همراه با قالب‌بندی فارسی و انگلیسی'), 'پزشکی که به فارسی دیکته می‌کند، به متنی با الفبای درست نیاز دارد که مقدارها و عبارت‌های نفی در آن حفظ شود. و ابزار دیکته نباید کلید API را روی همان دستگاهی که اجرا می‌شود به جا بگذارد.', 'یک ابزار دسکتاپ ویندوز: میکروفون ← نشست کوتاه‌عمر Deepgram ← نرمال‌سازی قطعی ← پردازش اصطلاحات پزشکی ← قالب‌بندی RTL/BiDi ← تزریق متن به هر پنجره‌ای که در فوکوس است، با یک پنجرهٔ شناورِ شروع/توقف و روکش اختیاریِ رونوشت.', JSON_ARRAY('کلید Deepgram هرگز از میزبان خارج نمی‌شود. برنامه با شناسهٔ کاربری و رازِ مخصوص دستگاه خود احراز هویت می‌کند؛ راز فقط به‌صورت یک بلوکِ محافظت‌شده با DPAPI در ویندوز ذخیره می‌شود و برنامه در برابر آن یک توکن نشستِ سی‌ثانیه‌ای می‌گیرد که فقط برای دست‌دهی WebSocket به کار می‌رود.', 'پردازش متن قطعی است نه مدل‌محور: نرمال‌سازی یونیکُد و ارقام، محافظت از عبارت‌های عددی بالینی و عبارت‌های نفی، و سپس یک بازنویسِ تطبیقِ طولانی‌ترین بر پایهٔ FST روی اصطلاح‌نامهٔ دسته‌بندی‌شده. در مسیر رونویسی یا اصلاح، هیچ مدل زبانی دخیل نیست.', 'تزریق متن پشت یک رابط InjectionBackend ایزوله شده است، بنابراین منطق تحویل را می‌توان بدون رابط گرافیکی ویندوز و با یک بک‌اند شبیه‌سازی آزمود؛ بک‌اند ویندوز از SendInput بومی و راهبردهای کلیپ‌بورد استفاده می‌کند.', 'نظارتی که روی نشست است شامل بازگشت نمایی برای اتصال دوباره، نگهبانِ ضبطِ خاموش، شمارش افتِ صدا و یک میانگیر بازیابی در حافظه برای متنی است که هرگز به پنجرهٔ مقصد نرسیده است.', 'یک لایهٔ انتزاع برای ارائه‌دهنده، Deepgram را پشت یک رابط نگه می‌دارد؛ لایه‌های پردازش و تزریق هرگز آن را وارد نمی‌کنند.'), 'یک ابزار کمکی دیکته که دربارهٔ چیستیِ خود صریح است: قطعی، قابل ردیابی و با محدودهٔ مشخص. این یک سامانهٔ NLP بالینی یا وسیلهٔ پزشکی نیست و مخزن همین را می‌گوید.', 'گفتار پزشکی فارسی — دیکتهٔ زنده برای ویندوز | امیرعلی غمخوار', 'مروری بر ابزار دیکتهٔ پزشکی فارسی و انگلیسی با توکن نشست کوتاه‌عمر، پردازش قطعی و قالب‌بندی متن.' FROM projects WHERE slug='deepgram-fa-speech';

SELECT id, 'en', 'Gamas Bot', 'Telegram study assistant', 'A Persian study assistant that turns audio and learning documents into transcripts, booklets, quizzes and flashcards.', 'Gamas Bot is a Telegram study assistant connecting audio, video, voice notes, and learning documents to structured study flows—from transcripts and booklets to quizzes, flashcards, and file exports.', JSON_ARRAY('Accepts audio, video, voice notes, and learning documents such as PDF and DOCX', 'Supports transcripts, structured booklets, quizzes, and flashcards', 'Includes a user library, support flows, and text and office-file exports'), 'Students record lectures on their phones and are left with nothing to revise from: hours of audio, or a PDF, and no structured way to study it. Turning that into notes by hand is slow, and transcription on its own does not produce something worth studying.', 'A Telegram bot that accepts audio, video, voice notes, PDFs, DOCX and PowerPoint files and returns study material: a transcript, a structured right-to-left Word booklet, quizzes, flashcards and file exports. Every file passes through an admission check, a bounded job queue and a user library, so the bot stays responsive under load.', JSON_ARRAY('One Telethon client with bounded asyncio stages and SQLite in WAL mode. Media work runs through PyAV in bounded child processes, so there is no message broker, no external database and no system FFmpeg installation.', 'Note generation uses an ordered provider chain: each route keeps its own key, base URL and model, transient failures retry within a fixed bound, and a recoverable provider error fails over to the next route.', 'Model output is parsed as strict JSON, validated for booklet shape and grounding before anything is rendered. A truncated completion is refused rather than delivered as a partial note.', 'Deterministic fallbacks cover document notes and Office conversion when no note-provider key is configured, so a missing credential degrades the feature instead of breaking it.', 'Logs carry metadata and token counts only — never keys, prompts, or transcript text.'), 'A single Python process that runs on Windows or cPanel shared hosting, with wallet credits and admin-reviewed receipts, support tickets and a referral flow wrapped around the learning features.', 'Gamas Bot — Telegram Study Assistant | Amirali Ghamkhar', 'A closer look at Gamas Bot, a Telegram study assistant for audio, documents, structured booklets, and learning tools.' FROM projects WHERE slug='gamas-bot';

SELECT id, 'en', 'Gamas Website', 'Product website', 'A Persian, right-to-left product site for Gamas, built as static pages with a small PHP API for shared hosting.', 'The Gamas Website is a Persian, right-to-left landing page for the study assistant. Its architecture pairs pre-rendered static HTML with a small PHP API for click analytics, so the site can run on Apache and cPanel without a persistent Node process.', JSON_ARRAY('Persian, right-to-left interface with pre-rendered static HTML', 'React 18, Vite 6, and vite-react-ssg in the build pipeline', 'A lightweight PHP 8.2+ API and deployment guidance for Apache and cPanel'), 'The bot needed a public home: a Persian, right-to-left product page that loads fast on shared hosting where Node.js is not available.', 'A static React 18 and Vite 6 site pre-rendered to HTML, paired with a small PHP 8.2 API for click analytics, deployed to Apache under cPanel.', JSON_ARRAY('Static pre-rendering with vite-react-ssg: every route ships as real HTML, so content and metadata are crawler-visible with no server-side process.', 'Persian webfonts are self-hosted and images are processed at build time, so the page does not depend on third-party font or CDN requests.', 'The API surface is reduced to an allow-listed set of endpoints with rate limiting and a CSP report collector.', 'Apache rules handle caching, compression, security headers and a static SPA fallback, so the site behaves on shared hosting exactly as it does in local preview.'), 'A product page that stays a set of static files: no runtime to maintain, no database to back up, and analytics that still work in a purely static deployment.', 'Gamas Website — Static Product Experience | Amirali Ghamkhar', 'The Persian Gamas product website: a static React and Vite experience with a lightweight PHP API for cPanel.' FROM projects WHERE slug='gamas-website';

SELECT id, 'en', 'Medical STT', 'Real-time medical dictation', 'A Windows desktop tool for Persian and English medical dictation, from a short-lived session token to right-to-left formatting and text injection.', 'This project is a real-time medical dictation aid for Windows. Audio uses a short-lived Deepgram session; the resulting text passes through normalization, terminology processing and bidirectional formatting before it is injected into whatever window is in focus.', JSON_ARRAY('Persian and English speech dictation on Windows', 'Short-lived session tokens minted by a self-hosted service; the Deepgram key is not placed in the desktop application', 'Deterministic terminology and text processing with Persian/English bidirectional formatting'), 'A clinician dictating in Persian needs text in the right script, with dosages and negation phrases preserved. And a dictation tool must not leave an API key behind on the machine it runs on.', 'A Windows desktop tool: microphone → short-lived Deepgram session → deterministic normalization → medical terminology processing → RTL/BiDi formatting → text injection into whatever window has focus, with a floating Start/Stop control and an optional transcript overlay.', JSON_ARRAY('The Deepgram key never leaves the operator’s host. The app authenticates with its own client id and per-device secret, stored only as a Windows DPAPI-protected blob, and receives a 30-second session token used for the WebSocket handshake.', 'Text processing is deterministic rather than model-based: Unicode and digit normalization, protection for clinical numeric expressions and negation phrases, then a longest-match FST rewriter over a categorized terminology catalog. No language model sits in the transcription or correction path.', 'Text injection sits behind an InjectionBackend interface, so delivery logic is testable through a dry-run backend with no Windows GUI; the Windows backend uses native SendInput and clipboard strategies.', 'Session supervision covers exponential reconnect backoff, a silent-capture watchdog, audio drop counting, and an in-memory recovery buffer for text that never reached the target window.', 'A provider abstraction keeps Deepgram behind one interface, so the processing and injection layers never import it.'), 'A dictation aid that is explicit about what it is: deterministic, auditable and scoped. It is not a clinical NLP system and not a medical device, and the repository says so.', 'Medical STT — Real-Time Persian Dictation | Amirali Ghamkhar', 'A closer look at a Persian and English medical dictation aid with short-lived session tokens and deterministic text processing.' FROM projects WHERE slug='deepgram-fa-speech';


SELECT id, 'fa', 'مهندسی هوش مصنوعی', 'عامل‌های LLM · خط‌لوله‌های هوش مصنوعی · گفتار به متن · تولید ساخت‌یافته', 'طراحی سامانه‌هایی که در آن‌ها مدل یک جزء است: جابه‌جایی مرتب میان ارائه‌دهنده‌ها، قرارداد خروجی سخت‌گیرانه، دروازهٔ اعتبارسنجی و ردِ صریحِ خروجی ناقص.' FROM expertise WHERE slug='ai-engineering';

SELECT id, 'fa', 'هوش مصنوعی پزشکی', 'دیکتهٔ بالینی · اصطلاحات پزشکی · پردازش قطعی · بیان محدودیت‌ها', 'کار در جایی که مدل زبانی ابزار درستی نیست: پردازشِ مبتنی بر قاعدهٔ اصطلاحات، محافظت از عبارت‌های عددی و نفی، و یادداشتِ روشنِ محدوده تا یک ابزار کمکی هرگز وانمود نکند سامانهٔ بالینی است.' FROM expertise WHERE slug='medical-ai';

SELECT id, 'fa', 'مهندسی نرم‌افزار', 'Python · TypeScript · APIها · SQLite · استقرار', 'تحویل کلِ چیز: همزمانیِ محدود، نوشتنِ تراکنشی، ذخیره‌سازیِ امن برای مهاجرت، و استقرارهایی که روی هاست اشتراکی یا یک دستگاه ویندوزی بدون زیرساخت اضافه بالا می‌آیند.' FROM expertise WHERE slug='software-engineering';

SELECT id, 'fa', 'پژوهش و ارزیابی', 'هوش مصنوعی سلامت · تکرارپذیری · ارزیابی · ادعای صادقانه', 'سنجیدنِ ادعاها دربارهٔ هوش مصنوعی کاربردی: خط‌لولهٔ ارزیابی، آزمون‌های جهش و پوشش، و نوشتنِ آنچه سامانه واقعاً انجام می‌دهد نه آنچه به نظر می‌رسد انجام می‌دهد.' FROM expertise WHERE slug='research-evaluation';

SELECT id, 'en', 'AI engineering', 'LLM applications · AI pipelines · speech-to-text · structured generation', 'Designing systems where the model is one component: ordered provider failover, strict output contracts, validation gates, and explicit refusal when a result comes back incomplete.' FROM expertise WHERE slug='ai-engineering';

SELECT id, 'en', 'Medical AI', 'Clinical dictation · medical terminology · deterministic processing · stated limits', 'Working where a language model is the wrong tool: rule-based terminology processing, protection for numeric and negation phrases, and scope notes that stop an assistive tool from ever presenting itself as a clinical system.' FROM expertise WHERE slug='medical-ai';

SELECT id, 'en', 'Software engineering', 'Python · TypeScript · APIs · SQLite · deployment', 'Shipping the whole thing: bounded concurrency, transactional writes, migration-safe storage, and deployments that run on shared hosting or a Windows machine without extra infrastructure.' FROM expertise WHERE slug='software-engineering';

SELECT id, 'en', 'Research & evaluation', 'Healthcare AI · reproducibility · benchmarking · honest claims', 'Testing claims about applied AI instead of repeating them: benchmark pipelines, mutation and coverage probes, and writing down what a system actually does rather than what it appears to do.' FROM expertise WHERE slug='research-evaluation';


SELECT id, 'fa', CASE slug WHEN 'artificial-intelligence' THEN 'هوش مصنوعی' WHEN 'medical-ai' THEN 'هوش مصنوعی پزشکی' WHEN 'ai-agents-llm-systems' THEN 'عامل‌های هوش مصنوعی و سامانه‌های LLM' WHEN 'medical-speech-processing' THEN 'بازشناسی گفتار و پردازش گفتار پزشکی' WHEN 'deterministic-output-evaluation' THEN 'پردازش قطعی و ارزیابی خروجی مدل' WHEN 'software-engineering' THEN 'مهندسی نرم‌افزار' WHEN 'technology-entrepreneurship' THEN 'کارآفرینی فناورانه' END, CASE slug WHEN 'artificial-intelligence' THEN 'مطالعهٔ سامانه‌های هوش مصنوعی کاربردی و مرزهای واقعی آن‌ها.' WHEN 'medical-ai' THEN 'کاربردهای سلامت‌محور با تأکید بر ابزارهای کمکی و محدودیت‌های صریح.' WHEN 'ai-agents-llm-systems' THEN 'طراحی عامل‌ها و خط‌لوله‌هایی که خروجی مدل را قابل اتکا می‌کنند.' WHEN 'medical-speech-processing' THEN 'گفتار به متن، اصطلاحات پزشکی و پردازش قطعیِ خروجی.' WHEN 'deterministic-output-evaluation' THEN 'اعتبارسنجی، محک‌زنی و تکرارپذیری در سامانه‌های مبتنی بر مدل.' WHEN 'software-engineering' THEN 'معماری، استقرار و نگهداریِ سامانه‌هایی که واقعاً اجرا می‌شوند.' WHEN 'technology-entrepreneurship' THEN 'تبدیل مسئله‌های واقعی به محصول، نه برعکس.' END FROM research;

SELECT id, 'en', CASE slug WHEN 'artificial-intelligence' THEN 'Artificial intelligence' WHEN 'medical-ai' THEN 'Medical AI' WHEN 'ai-agents-llm-systems' THEN 'AI agents and LLM systems' WHEN 'medical-speech-processing' THEN 'Speech recognition and medical speech processing' WHEN 'deterministic-output-evaluation' THEN 'Deterministic post-processing and output evaluation' WHEN 'software-engineering' THEN 'Software engineering' WHEN 'technology-entrepreneurship' THEN 'Technology entrepreneurship' END, CASE slug WHEN 'artificial-intelligence' THEN 'Studying applied AI systems and where their real limits are.' WHEN 'medical-ai' THEN 'Health applications, with attention to assistive tooling and explicit limits.' WHEN 'ai-agents-llm-systems' THEN 'Designing agents and pipelines that make model output dependable.' WHEN 'medical-speech-processing' THEN 'Speech-to-text, medical terminology, and deterministic post-processing.' WHEN 'deterministic-output-evaluation' THEN 'Validation, benchmarking, and reproducibility in model-backed systems.' WHEN 'software-engineering' THEN 'Architecture, deployment, and maintenance of systems that actually run.' WHEN 'technology-entrepreneurship' THEN 'Turning real problems into products, not the other way round.' END FROM research;


SELECT id, 'fa', CASE slug WHEN 'deepgram' THEN 'Deepgram' WHEN 'speech-to-text' THEN 'گفتار به متن' WHEN 'medical-dictation' THEN 'دیکتهٔ پزشکی' WHEN 'llm-apis' THEN 'APIهای مدل زبانی' WHEN 'react' THEN 'React' WHEN 'typescript' THEN 'TypeScript' WHEN 'javascript' THEN 'JavaScript' WHEN 'vite' THEN 'Vite' WHEN 'python' THEN 'Python' WHEN 'php' THEN 'PHP' WHEN 'mysql' THEN 'MySQL' WHEN 'sqlite' THEN 'SQLite' WHEN 'telethon' THEN 'Telethon' WHEN 'apache' THEN 'Apache' WHEN 'windows' THEN 'Windows' WHEN 'linux' THEN 'Linux' WHEN 'github-actions' THEN 'GitHub Actions' END, '' FROM technologies;

SELECT id, 'en', CASE slug WHEN 'deepgram' THEN 'Deepgram' WHEN 'speech-to-text' THEN 'Speech-to-text' WHEN 'medical-dictation' THEN 'Medical dictation' WHEN 'llm-apis' THEN 'LLM APIs' WHEN 'react' THEN 'React' WHEN 'typescript' THEN 'TypeScript' WHEN 'javascript' THEN 'JavaScript' WHEN 'vite' THEN 'Vite' WHEN 'python' THEN 'Python' WHEN 'php' THEN 'PHP' WHEN 'mysql' THEN 'MySQL' WHEN 'sqlite' THEN 'SQLite' WHEN 'telethon' THEN 'Telethon' WHEN 'apache' THEN 'Apache' WHEN 'windows' THEN 'Windows' WHEN 'linux' THEN 'Linux' WHEN 'github-actions' THEN 'GitHub Actions' END, '' FROM technologies;

SELECT p.id, t.id FROM projects p JOIN technologies t ON
  (p.slug='gamas-bot' AND t.slug IN ('python','telethon','sqlite','llm-apis','speech-to-text')) OR
  (p.slug='gamas-website' AND t.slug IN ('javascript','react','vite','php','apache')) OR
  (p.slug='deepgram-fa-speech' AND t.slug IN ('python','deepgram','windows','speech-to-text','medical-dictation'));

