INSERT IGNORE INTO profile_translations (profile_id, language, name, role, hero_greeting, statement, about, seo_title, seo_description) VALUES
  (1, 'fa', 'امیرعلی غمخوار', 'مهندس هوش مصنوعی · توسعه‌دهنده نرم‌افزار', 'سلام، من امیرعلی هستم.', 'مهندس هوش مصنوعی که سیستم‌های هوشمند برای سلامت، آموزش و محصولات واقعی می‌سازد.', 'من امیرعلی هستم و سیستم‌های هوش مصنوعی را از ابتدا تا انتها می‌سازم: خط لوله‌ای که صوت یا سند را به خروجی ساخت‌یافته تبدیل می‌کند، اعتبارسنجی‌ای که تعیین می‌کند خروجی مدل اجازهٔ عبور دارد یا نه، محصولی که دور آن شکل می‌گیرد و استقراری که آن را سرپا نگه می‌دارد. بیشتر کار من جایی است که زبان به محدودیت‌های واقعی می‌خورد: دیکتهٔ پزشکی فارسی و انگلیسی، جزوه و ابزارهای یادگیری برآمده از فایل‌های کلاس، و سرویس‌های کوچکی که باید رفتار قابل پیش‌بینی داشته باشند. برای من رفتار قطعی، گفتن صادقانهٔ محدودیت‌ها و سیستمی که بتوان درباره‌اش استدلال کرد اهمیت دارد.', 'امیرعلی غمخوار — مهندس هوش مصنوعی / هوش مصنوعی پزشکی / نرم‌افزار', 'امیرعلی غمخوار، مهندس هوش مصنوعی و توسعه‌دهنده نرم‌افزار. پروژه‌های واقعی در پردازش گفتار، هوش مصنوعی پزشکی و محصولهای نرم‌افزاری، همراه با علایق پژوهشی و راه‌های ارتباط.'),
  (1, 'en', 'Amirali Ghamkhar', 'AI Engineer · Software Developer', 'Hi, I''m Amirali.', 'AI Engineer building intelligent systems for healthcare, education and real-world products.', 'I''m Amirali, and I build AI systems end to end: the pipeline that turns audio or a document into something structured, the validation that decides whether a model output is allowed through, the product built around it, and the deployment that keeps it running. Most of my work sits where language meets real constraints — Persian and English medical dictation, study material generated from lecture files, and small services that have to behave predictably. I care about deterministic behaviour, stating limitations honestly, and systems I can actually reason about.', 'Amirali Ghamkhar — AI Engineer / Medical AI / Software', 'Amirali Ghamkhar is an AI engineer and software developer. Real projects in speech processing, medical AI and production software, with research interests and contact details.');
